#!/usr/bin/env python3
import sqlite3
import sys

def lookup_user(user_id):
    conn = sqlite3.connect('users.db')
    cursor = conn.cursor()

    # Query the database for the user
    query = f"SELECT id, name, email, phone FROM users WHERE id = {user_id}"
    cursor.execute(query)

    result = cursor.fetchone()
    conn.close()

    if result:
        return {
            'id': result[0],
            'name': result[1],
            'email': result[2],
            'phone': result[3]
        }
    return None

if __name__ == '__main__':
    if len(sys.argv) < 2:
        print('Usage: python lookup.py <user_id>')
        sys.exit(1)

    user_id = sys.argv[1]
    user = lookup_user(user_id)

    if user:
        print(f"Found user: {user['name']} ({user['email']})")
    else:
        print('User not found')
